import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"CLI","description":"kirivers server and admin add|delete|list|reset-password|clear-2fa. There is no listen subcommand.","frontmatter":{"title":"CLI","description":"kirivers server and admin add|delete|list|reset-password|clear-2fa. There is no listen subcommand."},"headers":[],"relativePath":"en/guide/cli.md","filePath":"en/guide/cli.md","lastUpdated":1790057721000}`),a={name:`en/guide/cli.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to “CLI”">​</a></h1><p>The executable entry is <code>kirivers</code>. With no positional arguments it starts the HTTP servers (same as <code>kirivers server</code>).</p><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>KiriVers — unified startup entry</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span>  kirivers [server] [-config path]                              start the HTTP servers (default)</span></span>
<span class="line"><span>                                                                client plane ... on client.yaml addr (:8080)</span></span>
<span class="line"><span>                                                                admin plane ... on admin.yaml addr (:8081)</span></span>
<span class="line"><span>  kirivers admin add &lt;username&gt; [-password secret]              create an instance admin</span></span>
<span class="line"><span>  kirivers admin delete &lt;username&gt;                              delete an instance admin</span></span>
<span class="line"><span>  kirivers admin list                                           list instance admins</span></span>
<span class="line"><span>  kirivers admin reset-password &lt;username&gt; [-password secret]   reset an admin password</span></span>
<span class="line"><span>  kirivers admin clear-2fa &lt;username&gt;                           clear TOTP, passkeys and recovery codes (does not revoke sessions)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>There is <strong>no</strong> <code>kirivers listen</code> subcommand. <code>cmd/listen.go</code> in the repository is TLS listen logic, not a CLI command.</p><h2 id="config-path" tabindex="-1">Config path <a class="header-anchor" href="#config-path" aria-label="Permalink to “Config path”">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Priority</th></tr></thead><tbody><tr><td><code>-config path</code></td><td>Highest</td></tr><tr><td><code>KIRIVERS_CONFIG</code></td><td>When <code>-config</code> is omitted</td></tr><tr><td>Default <code>configs/</code> then the current directory</td><td>When neither is set</td></tr></tbody></table><p><code>path</code> may be a file or a directory. Directory: <code>config.yaml</code> + <code>admin.yaml</code> + <code>client.yaml</code> in that folder. File: that system YAML plus sibling <code>admin.yaml</code> and <code>client.yaml</code>. Missing files fall back to sibling <code>*-example.yaml</code>.</p><p><code>kirivers admin</code> loads <strong>only</strong> the system <code>config.yaml</code> (database connection). It does not read <code>admin.yaml</code>.</p><p><code>-password</code> belongs to <code>admin</code> only. Passing it to <code>server</code> prints usage and exits <strong>2</strong>.</p><p>The examples below assume the three YAML files are in the working directory or <code>-config</code> is set.</p><h2 id="kirivers-kirivers-server" tabindex="-1"><code>kirivers</code> / <code>kirivers server</code> <a class="header-anchor" href="#kirivers-kirivers-server" aria-label="Permalink to “kirivers / kirivers server”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./configs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Success: the process stays up; logs show client and admin listen addresses. Failure: both log sinks disabled, PostgreSQL unreachable, or <code>cache.driver=redis</code> Ping failure → non-zero exit and no listen.</p><p>Common mistake: <code>-password</code> on server → stderr contains <code>-password is only valid with the admin command</code>, exit 2.</p><h2 id="kirivers-admin-add" tabindex="-1"><code>kirivers admin add</code> <a class="header-anchor" href="#kirivers-admin-add" aria-label="Permalink to “kirivers admin add”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Without <code>-password</code>, the process prompts on the terminal. Success:</p><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>created alice (&lt;uuid&gt;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="kirivers-admin-list" tabindex="-1"><code>kirivers admin list</code> <a class="header-anchor" href="#kirivers-admin-list" aria-label="Permalink to “kirivers admin list”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>USERNAME  ID                                    CREATED_AT</span></span>
<span class="line"><span>alice     11111111-1111-1111-1111-111111111111  2026-09-19T04:00:00Z</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="kirivers-admin-reset-password" tabindex="-1"><code>kirivers admin reset-password</code> <a class="header-anchor" href="#kirivers-admin-reset-password" aria-label="Permalink to “kirivers admin reset-password”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset-password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;new-secret&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Success: <code>password reset for alice</code></p><h2 id="kirivers-admin-clear-2fa" tabindex="-1"><code>kirivers admin clear-2fa</code> <a class="header-anchor" href="#kirivers-admin-clear-2fa" aria-label="Permalink to “kirivers admin clear-2fa”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear-2fa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Success: <code>cleared 2FA for alice</code></p><p>This clears TOTP, passkeys, and recovery codes. It does <strong>not</strong> revoke existing admin sessions.</p><h2 id="kirivers-admin-delete" tabindex="-1"><code>kirivers admin delete</code> <a class="header-anchor" href="#kirivers-admin-delete" aria-label="Permalink to “kirivers admin delete”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Success: <code>deleted alice</code>. Deleting the last instance admin fails (<code>LAST_ADMIN</code>).</p><p>Unknown commands or a missing username exit 2 and print usage.</p>`,32)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};